    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }

        let finalValue = Array.isArray(current) ? (current.length > 0 ? current[0] : defaultValue) : current;

        if (typeof finalValue === 'string' && finalValue.includes('->')) {
            const parts = finalValue.split('->');
            let newValue = parts[parts.length - 1].trim();
            const parenIndex = newValue.indexOf('(');
            if (parenIndex !== -1) {
                newValue = newValue.substring(0, parenIndex).trim();
            }
            finalValue = newValue;
        }

        return String(finalValue);
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 return;
            }

            document.getElementById('current-king').innerText = SafeGetValue(characterData, '当前国王', '无');
            document.getElementById('king-command').innerText = SafeGetValue(characterData, '国王命令', '无');

            document.getElementById('mika-behavior').innerText = SafeGetValue(characterData, '状态.美嘉.行为', '数据缺失');
            document.getElementById('mika-outfit').innerText = SafeGetValue(characterData, '状态.美嘉.装扮', '数据缺失');
            document.getElementById('mika-body').innerText = SafeGetValue(characterData, '状态.美嘉.身体', '数据缺失');

            document.getElementById('rin-behavior').innerText = SafeGetValue(characterData, '状态.凛.行为', '数据缺失');
            document.getElementById('rin-outfit').innerText = SafeGetValue(characterData, '状态.凛.装扮', '数据缺失');
            document.getElementById('rin-body').innerText = SafeGetValue(characterData, '状态.凛.身体', '数据缺失');

        } catch (error) {
            const card = document.getElementById('status-card');
            if (card) {
                card.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
            }
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
